"""Comprehensive tests for free_slots function."""

import pytest
from freebusy import free_slots

WEEK = ("mon", "tue", "wed", "thu", "fri")


class TestBasicFunctionality:
    """Test core free_slots functionality."""

    def test_single_attendee_one_working_day(self):
        """Single attendee on one working day."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_single_attendee_multiple_days(self):
        """Single attendee across multiple working days."""
        alice = {"tz": "UTC", "hours": {d: ["09:00-17:00"] for d in WEEK}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
        ]

    def test_no_working_hours_for_period(self):
        """Period has no working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-01T00:00Z", "2025-06-02T00:00Z", 30)
        assert result == []

    def test_no_overlap_between_attendees(self):
        """Two attendees with no overlapping working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-12:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["14:00-17:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == []

    def test_partial_overlap_between_attendees(self):
        """Two attendees with partial overlap."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-14:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["12:00-17:00"]}}
        result = free_slots([alice, bob], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z")]

    def test_three_attendees_full_overlap(self):
        """Three attendees with full overlap."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        bob = {"tz": "UTC", "hours": {"mon": ["10:00-16:00"]}}
        charlie = {"tz": "UTC", "hours": {"mon": ["11:00-15:00"]}}
        result = free_slots([alice, bob, charlie], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T11:00:00Z", "2025-06-02T15:00:00Z")]


class TestTimestampFormats:
    """Test various timestamp formats."""

    def test_timestamp_with_seconds(self):
        """Timestamps with seconds component."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_timestamp_without_seconds(self):
        """Timestamps without seconds component."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_timestamp_with_positive_offset(self):
        """Timestamps with positive UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00:00+05:30", "2025-06-02T17:00:00+05:30", 30)
        assert result == [("2025-06-02T03:30:00Z", "2025-06-02T11:30:00Z")]

    def test_timestamp_with_negative_offset(self):
        """Timestamps with negative UTC offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00:00-04:00", "2025-06-02T17:00:00-04:00", 30)
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T21:00:00Z")]

    def test_mixed_timestamp_formats(self):
        """Mixed timestamp formats in same call."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00:00-00:00", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_timestamp_at_midnight(self):
        """Timestamps at midnight."""
        alice = {"tz": "UTC", "hours": {"mon": ["00:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T00:00:00Z", "2025-06-03T00:00:00Z")]


class TestWorkingHours:
    """Test working hours specifications."""

    def test_regular_hours_start_before_end(self):
        """Regular working hours where start < end (09:00-17:00)."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_overnight_hours_end_before_start(self):
        """Overnight working hours where end < start (22:00-06:00)."""
        alice = {"tz": "UTC", "hours": {"fri": ["22:00-06:00"]}}
        result = free_slots([alice], "2025-06-06T00:00Z", "2025-06-07T00:00Z", 30)
        # Friday 22:00 to Saturday 06:00
        assert result == [("2025-06-06T22:00:00Z", "2025-06-07T06:00:00Z")]

    def test_midnight_end_time(self):
        """Working hours with 24:00 as end time."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-03T00:00:00Z")]

    def test_midnight_start_time(self):
        """Working hours starting at 00:00."""
        alice = {"tz": "UTC", "hours": {"mon": ["00:00-12:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-02T12:00Z", 30)
        assert result == [("2025-06-02T00:00:00Z", "2025-06-02T12:00:00Z")]

    def test_multiple_entries_same_day(self):
        """Multiple working hour entries on the same day."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-12:00", "14:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_overlapping_entries_same_day(self):
        """Overlapping working hour entries on the same day."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-15:00", "12:00-18:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Overlapping entries should be merged effectively
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T18:00:00Z")]

    def test_missing_weekday_no_hours(self):
        """Weekday missing from hours dict has no working hours."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"], "tue": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-01T00:00Z", "2025-06-04T00:00Z", 30)
        # Sunday (06-01), Monday (06-02), Tuesday (06-03), Wednesday (06-04)
        # Only Monday and Tuesday have working hours
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z"),
            ("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z"),
        ]

    def test_empty_hours_list_means_no_hours(self):
        """Empty hours list for a weekday means no working hours."""
        alice = {"tz": "UTC", "hours": {"mon": [], "tue": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-04T00:00Z", 30)
        # Monday has empty list (no hours), Tuesday has hours
        assert result == [("2025-06-03T09:00:00Z", "2025-06-03T17:00:00Z")]

    def test_single_minute_hour(self):
        """Very short working hour window."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:01"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T09:01:00Z")]


class TestBusyPeriods:
    """Test busy period handling."""

    def test_single_busy_period(self):
        """Single busy period cuts into working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_multiple_busy_periods(self):
        """Multiple busy periods."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T11:00:00Z"],
                ["2025-06-02T13:00:00Z", "2025-06-02T14:30:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T11:00:00Z", "2025-06-02T13:00:00Z"),
            ("2025-06-02T14:30:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_overlapping_busy_periods(self):
        """Overlapping busy periods."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z"],
                ["2025-06-02T11:00:00Z", "2025-06-02T14:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_touching_busy_periods(self):
        """Busy periods that touch each other."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z"],
                ["2025-06-02T12:00:00Z", "2025-06-02T14:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T14:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_busy_period_covers_all_working_hours(self):
        """Busy period covers entire working hours."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T08:00:00Z", "2025-06-02T18:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == []

    def test_busy_period_outside_window(self):
        """Busy period outside search window is irrelevant."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T18:00:00Z", "2025-06-02T20:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_busy_period_partially_overlaps_window(self):
        """Busy period partially overlaps search window."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T07:00:00Z", "2025-06-02T12:00:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T10:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T12:00:00Z", "2025-06-02T17:00:00Z")]

    def test_no_busy_field_means_never_busy(self):
        """Missing 'busy' field means attendee is never busy."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]


class TestMinutesFilter:
    """Test min_minutes filtering."""

    def test_min_minutes_one(self):
        """Minimum 1 minute."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T12:01:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T12:01:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_min_minutes_filters_short_slots(self):
        """Slots shorter than min_minutes are excluded."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T10:00:00Z", "2025-06-02T10:30:00Z"],
                ["2025-06-02T11:00:00Z", "2025-06-02T12:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 60)
        # First slot: 09:00-10:00 (60 min, included)
        # Second slot: 10:30-11:00 (30 min, excluded)
        # Third slot: 12:00-17:00 (300 min, included)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T10:00:00Z"),
            ("2025-06-02T12:00:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_min_minutes_exact_boundary(self):
        """Slot exactly at min_minutes boundary."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [["2025-06-02T12:00:00Z", "2025-06-02T13:30:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 90)
        # First slot: 09:00-12:00 (180 min, included)
        # Second slot: 13:30-17:00 (210 min, included)
        assert result == [
            ("2025-06-02T09:00:00Z", "2025-06-02T12:00:00Z"),
            ("2025-06-02T13:30:00Z", "2025-06-02T17:00:00Z"),
        ]

    def test_min_minutes_all_slots_filtered(self):
        """All free slots are too short."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": [
                ["2025-06-02T09:30:00Z", "2025-06-02T09:40:00Z"],
                ["2025-06-02T09:50:00Z", "2025-06-02T17:00:00Z"],
            ],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        # Slots are 30 min (09:00-09:30) and 10 min (09:40-09:50)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T09:30:00Z")]


class TestTimeZones:
    """Test time zone handling."""

    def test_utc_timezone(self):
        """UTC time zone."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_eastern_timezone(self):
        """America/New_York time zone."""
        alice = {"tz": "America/New_York", "hours": {"mon": ["09:00-17:00"]}}
        # 09:00-17:00 in NY (UTC-4 in June) is 13:00-21:00 UTC
        result = free_slots([alice], "2025-06-02T13:00Z", "2025-06-02T21:00Z", 30)
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T21:00:00Z")]

    def test_berlin_timezone(self):
        """Europe/Berlin time zone."""
        alice = {"tz": "Europe/Berlin", "hours": {"mon": ["09:00-17:00"]}}
        # 09:00-17:00 in Berlin (UTC+2 in June) is 07:00-15:00 UTC
        result = free_slots([alice], "2025-06-02T07:00Z", "2025-06-02T15:00Z", 30)
        assert result == [("2025-06-02T07:00:00Z", "2025-06-02T15:00:00Z")]

    def test_tokyo_timezone(self):
        """Asia/Tokyo time zone."""
        alice = {"tz": "Asia/Tokyo", "hours": {"mon": ["09:00-17:00"]}}
        # 09:00-17:00 in Tokyo (UTC+9) is 00:00-08:00 UTC
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-02T08:00Z", 30)
        assert result == [("2025-06-02T00:00:00Z", "2025-06-02T08:00:00Z")]

    def test_different_timezones_multiple_attendees(self):
        """Multiple attendees in different time zones."""
        ny = {"tz": "America/New_York", "hours": {"mon": ["09:00-17:00"]}}
        berlin = {"tz": "Europe/Berlin", "hours": {"mon": ["09:00-17:00"]}}
        # NY: 13:00-21:00 UTC, Berlin: 07:00-15:00 UTC, overlap: 13:00-15:00
        result = free_slots([ny, berlin], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T15:00:00Z")]


class TestDSTTransitions:
    """Test daylight saving time transitions."""

    def test_spring_forward_nyc_2025(self):
        """Spring forward in New York (2025-03-09)."""
        alice = {"tz": "America/New_York", "hours": {"sun": ["02:30-04:00"]}}
        # On 2025-03-09, clocks jump from 02:00 EST to 03:00 EDT at 07:00Z
        # So 02:30-04:00 (which doesn't exist as written) becomes 03:00-04:00 EDT
        result = free_slots([alice], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # 02:30-04:00 covers 07:00Z-08:00Z (03:00-04:00 EDT)
        assert result == [("2025-03-09T07:00:00Z", "2025-03-09T08:00:00Z")]

    def test_spring_forward_skipped_time(self):
        """Spring forward with entry that gets skipped (02:10-02:50)."""
        alice = {"tz": "America/New_York", "hours": {"sun": ["02:10-02:50"]}}
        # This time range is entirely skipped by DST
        result = free_slots([alice], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        assert result == []

    def test_fall_back_nyc_2025(self):
        """Fall back in New York (2025-11-02)."""
        alice = {"tz": "America/New_York", "hours": {"sun": ["00:00-03:00"]}}
        # On 2025-11-02, clocks go back from 02:00 EDT to 01:00 EST at 06:00Z
        # 00:00-03:00 covers 04:00-08:00Z (four hours: 00:00-02:00 EDT then 01:00-02:00 EST)
        result = free_slots([alice], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        assert result == [("2025-11-02T04:00:00Z", "2025-11-02T08:00:00Z")]

    def test_fall_back_repeated_time(self):
        """Fall back with entry covering repeated times."""
        alice = {"tz": "America/New_York", "hours": {"sun": ["01:30-09:00"]}}
        # 01:30-09:00 covers 05:30Z-06:00Z (EDT) and 06:30Z-14:00Z (EST)
        # Skips 06:00-06:30Z when clock shows 01:00-01:29 for the second time
        result = free_slots([alice], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # Should return two slots with a gap in between
        assert len(result) == 2
        assert result[0] == ("2025-11-02T05:30:00Z", "2025-11-02T06:00:00Z")
        assert result[1] == ("2025-11-02T06:30:00Z", "2025-11-02T14:00:00Z")

    def test_no_dst_transition(self):
        """No DST transition in the period."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 30)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]


class TestMaximalFreePeriods:
    """Test that free periods are maximal (not split unnecessarily)."""

    def test_continuous_free_time_across_day_boundary(self):
        """Free time spanning across day boundary (not split)."""
        alice = {"tz": "UTC", "hours": {"sun": ["12:00-24:00"], "mon": ["00:00-12:00"]}}
        result = free_slots([alice], "2025-06-01T00:00Z", "2025-06-03T00:00Z", 1)
        # Free: Sun 12:00-Mon 12:00 (continuous, 24 hours)
        assert result == [("2025-06-01T12:00:00Z", "2025-06-02T12:00:00Z")]

