class TestDSTEdgeCases:
    """Test edge cases around Daylight Saving Time transitions."""

    def test_spring_forward_ny_2025(self):
        """Spring forward in New York on March 9, 2025."""
        # Clocks jump from 02:00 EST to 03:00 EDT at 07:00Z
        ny = {"tz": "America/New_York", "hours": {"sun": ["02:30-04:00"]}}
        result = free_slots([ny], "2025-03-09T06:00Z", "2025-03-09T09:00Z", 30)
        # The 02:30 time doesn't exist on that day (02:00 becomes 03:00)
        # 02:30 is "skipped", so entry doesn't cover it
        # Result should not include any time, or only 03:00-04:00 EDT
        assert isinstance(result, list)

    def test_fall_back_ny_2025(self):
        """Fall back in New York on November 2, 2025."""
        # Clocks go from 01:59 EDT back to 01:00 EST at 06:00Z
        # 01:00-01:59 is repeated
        ny = {"tz": "America/New_York", "hours": {"sun": ["00:00-03:00"]}}
        result = free_slots([ny], "2025-11-02T04:00Z", "2025-11-02T08:00Z", 30)
        # This covers the entire period in EDT and then some in EST
        assert isinstance(result, list)

    def test_working_hours_in_skipped_time(self):
        """Working hours that would be skipped during spring forward."""
        ny = {"tz": "America/New_York", "hours": {"sun": ["02:10-02:50"]}}
        # This range is entirely skipped during spring forward on 2025-03-09
        result = free_slots([ny], "2025-03-09T06:00Z", "2025-03-09T09:00Z", 30)
        # Should return empty since the time is skipped
        assert result == []

    def test_working_hours_during_repeated_time_fall_back(self):
        """Working hours that cover repeated time during fall back."""
        ny = {"tz": "America/New_York", "hours": {"sun": ["01:30-09:00"]}}
        # This covers the repeated 01:30-01:59 during fall back
        result = free_slots([ny], "2025-11-02T04:00Z", "2025-11-02T08:00Z", 30)
        # Result should include both occurrences of the repeated time
        assert isinstance(result, list)


