class TestEdgeCasesAndBoundaries:
    """Test edge cases and boundary conditions."""

    def test_single_minute_slot(self):
        """Find a single minute free slot."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-10:00"]},
            "busy": [["2025-06-02T09:00:00Z", "2025-06-02T09:59:00Z"]],
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T09:59:00Z", "2025-06-02T10:00:00Z")]

    def test_midnight_boundary(self):
        """Free slots at midnight boundary."""
        alice = {"tz": "UTC", "hours": {"mon": ["23:00-24:00"], "tue": ["00:00-02:00"]}}
        result = free_slots([alice], "2025-06-02T22:00Z", "2025-06-04T00:00Z", 30)
        # Mon 23-00 and Tue 00-02 form one continuous slot
        assert len(result) >= 1

    def test_long_window_no_working_hours(self):
        """Long search window with no attendee working hours."""
        alice = {"tz": "UTC", "hours": {}}
        result = free_slots([alice], "2025-06-01T00:00Z", "2025-06-30T00:00Z", 60)
        assert result == []

    def test_large_number_of_busy_periods(self):
        """Attendee with many busy periods."""
        busy_periods = [[f"2025-06-02T{h:02d}:00:00Z", f"2025-06-02T{h:02d}:15:00Z"] for h in range(10, 17)]
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["09:00-17:00"]},
            "busy": busy_periods,
        }
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 10)
        # Should have gaps between busy periods
        assert len(result) > 0

    def test_window_spans_multiple_weeks(self):
        """Search window spans multiple weeks."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-16T00:00Z", 30)
        # Should find Monday slots on June 2, 9, and 16
        assert len(result) >= 1

    def test_attendee_timezone_different_from_input_offset(self):
        """Timestamps with different UTC offset than attendee timezone."""
        # Attendee in Tokyo, but timestamps given with different offset
        tokyo = {"tz": "Asia/Tokyo", "hours": {"mon": ["09:00-17:00"]}}
        # Timestamp written as +05:00 instead of +09:00, but still represents same instant
        result = free_slots([tokyo], "2025-06-02T04:00:00+05:00", "2025-06-02T12:00:00+05:00", 30)
        assert isinstance(result, list)

    def test_very_early_hours(self):
        """Working hours at very early morning."""
        alice = {"tz": "UTC", "hours": {"mon": ["00:00-02:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T00:00:00Z", "2025-06-02T02:00:00Z")]

    def test_very_late_hours(self):
        """Working hours at very late night."""
        alice = {"tz": "UTC", "hours": {"mon": ["22:00-24:00"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 30)
        assert result == [("2025-06-02T22:00:00Z", "2025-06-03T00:00Z")]

    def test_one_minute_work_window(self):
        """Very short working hours (1 minute)."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-09:01"]}}
        result = free_slots([alice], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T09:01:00Z")]

    def test_mixed_timezone_offset_formats(self):
        """Mix of +HH:MM and Z offset formats in timestamps."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T00:00:00+00:00", "2025-06-02T23:59:00Z", 30)
        assert isinstance(result, list)

