class TestTimezones:
    """Test time zone handling across different zones."""

    def test_single_timezone_utc(self):
        """Single attendee in UTC."""
        alice = {"tz": "UTC", "hours": {"mon": ["10:00-12:00"]}}
        result = free_slots([alice], "2025-06-02T10:00Z", "2025-06-02T12:00Z", 1)
        assert result == [("2025-06-02T10:00:00Z", "2025-06-02T12:00:00Z")]

    def test_different_timezones_new_york_berlin(self):
        """Two attendees in different timezones with overlapping work hours."""
        ny = {"tz": "America/New_York", "hours": {d: ["09:00-17:00"] for d in WEEKDAYS}}
        berlin = {
            "tz": "Europe/Berlin",
            "hours": {d: ["09:00-17:00"] for d in WEEKDAYS},
        }
        result = free_slots([ny, berlin], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1)
        # NY 09:00-17:00 EDT (UTC-4) = 13:00-21:00 UTC
        # Berlin 09:00-17:00 CEST (UTC+2) = 07:00-15:00 UTC
        # Overlap: 13:00-15:00 UTC
        assert len(result) == 1
        assert result[0][0] == "2025-06-02T13:00:00Z"
        assert result[0][1] == "2025-06-02T15:00:00Z"

    def test_tokyo_sydney_overlap(self):
        """Two attendees in Asia-Pacific timezones."""
        tokyo = {"tz": "Asia/Tokyo", "hours": {d: ["09:00-18:00"] for d in WEEKDAYS}}
        sydney = {
            "tz": "Australia/Sydney",
            "hours": {d: ["09:00-18:00"] for d in WEEKDAYS},
        }
        # Finding the overlap requires understanding the time zone offsets
        result = free_slots(
            [tokyo, sydney], "2025-06-02T00:00Z", "2025-06-03T00:00Z", 1
        )
        # Both should have some working hours during the day
        assert isinstance(result, list)


