    def test_utc_offset_plus_hhmm(self):
        """Timestamp with +HH:MM offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00+00:00", "2025-06-02T17:00+00:00", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_utc_offset_minus_hhmm(self):
        """Timestamp with -HH:MM offset."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00-04:00", "2025-06-02T17:00-04:00", 1)
        # 09:00-04:00 = 13:00 UTC, 17:00-04:00 = 21:00 UTC
        # Working hours mon 09:00-17:00 UTC
        # Overlap: 13:00-17:00 UTC
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T17:00:00Z")]

    def test_timestamp_with_seconds(self):
        """Timestamp with seconds (must be :00)."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z", 1)
        assert result == [("2025-06-02T09:00:00Z", "2025-06-02T17:00:00Z")]

    def test_different_offsets_same_instant(self):
        """Same instant represented with different UTC offsets."""
        alice = {
            "tz": "UTC",
            "hours": {"mon": ["12:00-14:00"]},
            "busy": [["2025-06-02T12:00+00:00", "2025-06-02T13:00+00:00"]],
        }
        result = free_slots([alice], "2025-06-02T12:00Z", "2025-06-02T14:00Z", 1)
        # Busy is 12:00-13:00 UTC, working is 12:00-14:00 UTC
        # Free is 13:00-14:00 UTC
        assert result == [("2025-06-02T13:00:00Z", "2025-06-02T14:00:00Z")]

    def test_output_format_utc_z(self):
        """Output timestamps should be in UTC with Z suffix."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        # Check that all output timestamps end with Z
        for start, end in result:
            assert start.endswith("Z")
            assert end.endswith("Z")
            assert "T" in start
            assert "T" in end

    def test_output_format_includes_seconds(self):
        """Output timestamps should include seconds."""
        alice = {"tz": "UTC", "hours": {"mon": ["09:00-17:00"]}}
        result = free_slots([alice], "2025-06-02T09:00Z", "2025-06-02T17:00Z", 1)
        # Check format YYYY-MM-DDTHH:MM:SSZ
        for start, end in result:
            assert len(start) == 20  # YYYY-MM-DDTHH:MM:SSZ


class TestDSTTransitions:
    """Test daylight saving time transitions."""

    def test_spring_forward_america_new_york(self):
        """DST spring forward in America/New_York (2025-03-09)."""
        alice = {
            "tz": "America/New_York",
            "hours": {"sun": ["00:00-24:00"]},
        }
        # Clocks jump from 02:00 EST to 03:00 EDT
        result = free_slots([alice], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # Should still have full day (23 hours due to DST)
        assert len(result) >= 1

    def test_fall_back_america_new_york(self):
        """DST fall back in America/New_York (2025-11-02)."""
        alice = {
            "tz": "America/New_York",
            "hours": {"sun": ["00:00-24:00"]},
        }
        # Clocks go from 02:00 EDT back to 01:00 EST
        result = free_slots([alice], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # Should still have full day (25 hours due to DST)
        assert len(result) >= 1

    def test_hours_during_spring_forward(self):
        """Working hours during spring forward transition."""
        alice = {
            "tz": "America/New_York",
            "hours": {"sun": ["02:30-04:00"]},
        }
        # Entry 02:30-04:00 on Sunday with spring forward
        result = free_slots([alice], "2025-03-09T00:00Z", "2025-03-10T00:00Z", 1)
        # Clocks jump at 02:00 EST (07:00 UTC), so 02:30 EST doesn't exist
        # 02:30-04:00 becomes 07:00-08:00 UTC (03:00-04:00 EDT)
        assert isinstance(result, list)

    def test_hours_during_fall_back(self):
        """Working hours during fall back transition."""
        alice = {
            "tz": "America/New_York",
            "hours": {"sun": ["00:00-03:00"]},
        }
        # Entry 00:00-03:00 on Sunday with fall back
        result = free_slots([alice], "2025-11-02T00:00Z", "2025-11-03T00:00Z", 1)
        # Clocks go back at 02:00 EDT (06:00 UTC), so 00:00-03:00 appears twice
        # First: 04:00-06:00 UTC (00:00-02:00 EDT)
        # Then: 05:00-08:00 UTC (01:00-03:00 EST)
        # Total coverage: 04:00-08:00 UTC with gap from 06:00-05:00 (which wraps, doesn't happen)
        # Actually: 04:00-06:00 and 05:00-08:00 = 04:00-08:00
        assert isinstance(result, list)


